import os
from typing import Optional

from google.api_core.exceptions import GoogleAPICallError, RetryError
from google.cloud import pubsub_v1


class DeadLetterPublisher:
    def __init__(self, project_id: str, topic_id: str) -> None:
        self.project_id = project_id
        self.topic_id = topic_id
        self.publisher = pubsub_v1.PublisherClient()
        self.topic_path = self.publisher.topic_path(project_id, topic_id)

    def send_failed_message(
        self,
        message_data: bytes,
        original_message_id: Optional[str] = None,
        error_reason: Optional[str] = None,
        source_subscription: Optional[str] = None,
    ) -> str:
        if not isinstance(message_data, (bytes, bytearray)):
            raise TypeError("message_data must be bytes")

        attributes = {
            "dead_letter": "true",
        }

        if original_message_id:
            attributes["original_message_id"] = original_message_id
        if error_reason:
            attributes["error_reason"] = error_reason
        if source_subscription:
            attributes["source_subscription"] = source_subscription

        future = self.publisher.publish(
            self.topic_path,
            bytes(message_data),
            **attributes,
        )
        return future.result(timeout=30)


def send_to_dead_letter_topic(
    message_data: bytes,
    original_message_id: Optional[str] = None,
    error_reason: Optional[str] = None,
    source_subscription: Optional[str] = None,
) -> str:
    project_id = os.environ["GOOGLE_CLOUD_PROJECT"]
    dead_letter_topic_id = os.environ["GOOGLE_CLOUD_PUBSUB_DEAD_LETTER_TOPIC"]

    publisher = DeadLetterPublisher(project_id, dead_letter_topic_id)

    try:
        return publisher.send_failed_message(
            message_data=message_data,
            original_message_id=original_message_id,
            error_reason=error_reason,
            source_subscription=source_subscription,
        )
    except (GoogleAPICallError, RetryError) as exc:
        raise RuntimeError(f"Failed to publish to Google Cloud Pub/Sub dead-letter topic: {exc}") from exc
